import { presetStrokeColors } from '../presets';
const dedicatedStrokeColors = {
  default: "var(--ds-border-dropindicator, #357DE8)",
  warning: "var(--ds-border-dropindicator-warning, #E06C00)"
};
export function getStrokeColor(appearance, colors) {
  return colors === 'dedicated' ? dedicatedStrokeColors[appearance] : presetStrokeColors[appearance];
}